"""Generate PR prose from audited data; this script does not publish anything."""
import json,sys
from pathlib import Path
D=Path(__file__).resolve().parent
v=json.loads((D/'summary.json').read_text());assert v['status']=='audited'
evidence=sys.argv[1]
url=f'https://github.com/MollySophia/memory-attention/blob/{evidence}/profile/results/pr-offload-001/'
lines=['CPU memory-table offload lets `MemoryForCausalLM` keep its large table weights on the host during CUDA inference. Previously, model inference required GPU-resident table embeddings. The resident path remains the default; callers explicitly enable and close offload under inference mode.','', 'Normalization is folded once into the table. Bounded staging overlaps CPU lookup and H2D transfer with layer computation; small inputs can read pinned host rows directly. Host scheduling lives in `fla/layers/memory_offload.py`, the Triton gather in `fla/ops/memory/`, and regression tests in `tests/models/test_memory_offload.py`.','', '### Validation','', '- 49 CUDA regression cases pass; Ruff passes on all changed Python files.', '- Coverage includes 128-step growing KV caches, padding, hidden states, fresh table mutations, cross-stream buffer lifetimes, exception cleanup and layer hooks.', '- Review fixed two lifecycle issues: evicted offloaders are closed, and closing a folded table clears the raw-weight snapshot so later updates are not overwritten. Both have regression tests.', '- Fresh full-model comparisons across upstream main, PR folded GPU and PR offload are bit-exact at batch1/8, prefix2048, seed1234: logits at all129 steps, all25 hidden states and24 layer KV states at prefix and steps1/2/128.','', '### Fresh performance: upstream main → PR head','',f"Measured source commits: upstream `{v['sources']['main'][1]}` and PR `{v['sources']['head'][1]}`. All rows below are newly collected from those exact commits, replacing the earlier pre-refactor measurements.",'', 'RTX5090; 24 layers, 2.8365B BF16; fixed random weights/input tokens. Three independent process blocks rotate placement order. Prefill/decode use10 warmups and10 samples×3 rounds per process; generation uses2 warmups and5 trajectories×3 rounds. Means below are in milliseconds. Paired intervals use process means (95% Student-t, df=2), not individual timing samples as independent replicates.','', 'Prefill includes KV construction and last-token logits. Decode measures one step at fixed context. Generation includes a2048-token prefix plus128 growing-cache decode steps with predetermined tokens, excluding sampling. Loading, folding and buffer setup are excluded.','', '| Workload | Batch | Length/context | Before: main GPU | After: PR offload | Change vs main | PR folded GPU | Offload−folded gap (95% CI), ms |','| --- | ---: | ---: | ---: | ---: | ---: | ---: | --- |']
for r in v['rows']:
 def val(label):
  p=r['placements'][label];return f"{p['mean_ms']:.3f}" if p['status']=='completed' else 'OOM'
 change=f"{r['offload_vs_main_pct']['mean']:+.2f}%" if 'offload_vs_main_pct' in r else '—'
 if 'offload_minus_folded_gpu_ms' in r:
  g=r['offload_minus_folded_gpu_ms'];gap=f"{g['mean']:+.3f} [{g['lower_95']:+.3f}, {g['upper_95']:+.3f}]"
 else:gap='unavailable'
 lines.append(f"| {r['mode']} | {r['batch']} | {r['length']} | {val('main_gpu')} | {val('head_offload')} | {change} | {val('head_gpu')} | {gap} |")
lines+=['','Negative latency change is faster. The main-to-offload comparison includes normalization folding; the folded-GPU column separates that benefit from the incremental offload cost. Intervals crossing zero are inconclusive, not equivalence. The results do not establish a universal1% overhead bound.','', '### Memory','', '| Prefill batch/context | Main peak GPU GiB | PR offload peak GPU GiB | Saved GiB | Offload pinned host GiB |','| --- | ---: | ---: | ---: | ---: |']
for r in v['rows']:
 if r['mode']!='prefill':continue
 a,b=r['placements']['main_gpu'],r['placements']['head_offload']
 if a['status']==b['status']=='completed':lines.append(f"| {r['batch']}/{r['length']} | {a['gpu_peak_allocated_gib']:.3f} | {b['gpu_peak_allocated_gib']:.3f} | {a['gpu_peak_allocated_gib']-b['gpu_peak_allocated_gib']:.3f} | {b['host_pinned_gib']:.3f} |")
 else:lines.append(f"| {r['batch']}/{r['length']} | OOM | OOM | — | — |")
lines+=['','GPU values are peak allocated memory, not reserved or nvidia-smi usage. Host storage also includes raw restoration weights and process overhead; offload saves GPU residency, not total model size. A separate approximately654MiB GPU allocation was present and is recorded in telemetry.','', f'[Full report]({url}REPORT.md) · [CSV]({url}summary.csv) · [Paired statistics and environment audit]({url}summary.json) · [Frozen plan, commands and raw-result index]({url}manifest.json) · [Comparison figure]({url}comparison.png)','', '### Scope and limitations','', 'CUDA inference only; backward with offload is unsupported. Load weights and move the model to the target device before enabling offload, and close offload before checkpoint serialization. Multi-GPU and non-CUDA support are not established. Fixed random weights support performance/numerical claims, not language quality.', '', 'Batch64 OOM results are preserved, including failure during decode prefix construction; identical-cell repeats were skipped under the frozen rule, never recorded as zero latency. One initial main process wrote complete timing data before its cleanup called an absent offload API; that post-measurement compatibility error was audited and fixed without discarding or rerunning its samples. Timed routines were unchanged.', '', 'The PR remains a draft for maintainer review; performance comparisons above now measure the actual PR head.']
text='\n'.join(lines)+'\n'
for a,b in [('RTX5090','RTX 5090'),('batch1/8','batch 1/8'),('prefix2048','prefix 2048'),('seed1234','seed 1234'),('all129','all 129'),('all25','all 25'),('and24','and 24'),('steps1/2/128','steps 1/2/128'),('use10','use 10'),('and10','and 10'),('samples×3','samples × 3'),('uses2','uses 2'),('and5','and 5'),('trajectories×3','trajectories × 3'),('a2048','a 2048'),('plus128','plus 128'),('universal1%','universal 1%'),('approximately654MiB','approximately 654 MiB'),('Batch64','Batch 64')]:text=text.replace(a,b)
print(text,end='')
